mapper.select:
SELECT * FROM im_sessions
WHERE user1_id = #{userId} OR user2_id = #{userId}
ORDER BY last_message_at DESC

mapper.update:
UPDATE im_sessions
SET user1_unread_count = CASE WHEN user1_id = #{userId} THEN 0 ELSE COALESCE(user1_unread_count, 0) END,
    user2_unread_count = CASE WHEN user2_id = #{userId} THEN 0 ELSE COALESCE(user2_unread_count, 0) END,
    is_active = CASE WHEN EXISTS (
        SELECT 1 FROM im_messages m
        WHERE m.session_id = #{sessionId}
          AND m.sender_id = #{userId}
          AND m.sender_type = 1
    ) THEN 1 ELSE is_active END
WHERE id = #{sessionId}
